// SmartHelmet/Software/src/components/SurveillanceTunnelMap.jsx

import { useMemo } from 'react';
import { TUNNEL_GRAPH, THRESHOLDS } from '../utils/constants';
import { runDijkstra } from '../services/api';
import '../styles/SurveillanceTunnelMap.css';

/* ═══════════════════════════════════════════════════════
   CINEMATIC MINE MAP — Layout & Topology Constants
   ViewBox: 0 0 900 500
   ═══════════════════════════════════════════════════════ */

const VB_W = 900;
const VB_H = 500;

/** Handcrafted node positions for cinematic mine layout */
const NODES = {
  'Entrance':       { x: 90,  y: 310 },
  'Main Junction':  { x: 290, y: 280 },
  'West Junction':  { x: 450, y: 140 },
  'East Junction':  { x: 600, y: 360 },
  'Zone A':         { x: 350, y: 65  },
  'Zone B':         { x: 530, y: 220 },
  'Zone C':         { x: 750, y: 180 },
};

/** Main tunnel edges — cubic Bézier curves for organic shape */
const EDGES = [
  { from: 'Entrance',      to: 'Main Junction',  d: 'M90,310 C145,306 215,292 290,280' },
  { from: 'Main Junction', to: 'West Junction',   d: 'M290,280 C308,252 378,178 450,140' },
  { from: 'Main Junction', to: 'East Junction',   d: 'M290,280 C338,296 475,338 600,360' },
  { from: 'West Junction', to: 'Zone A',          d: 'M450,140 C428,108 388,78 350,65' },
  { from: 'West Junction', to: 'Zone B',          d: 'M450,140 C458,165 498,198 530,220' },
  { from: 'East Junction', to: 'Zone B',          d: 'M600,360 C585,312 555,252 530,220' },
  { from: 'East Junction', to: 'Zone C',          d: 'M600,360 C638,318 700,242 750,180' },
].map((e) => ({ ...e, key: [e.from, e.to].sort().join('|') }));

/** Layered stroke specs for organic tunnel rendering */
const TUNNEL_LAYERS = [
  { w: 24,  c: 'rgba(0,120,190,0.045)' },
  { w: 14,  c: 'rgba(0,150,215,0.09)'  },
  { w: 6,   c: 'rgba(0,185,240,0.2)'   },
  { w: 2.2, c: 'rgba(0,210,255,0.42)'  },
];

const BRANCH_LAYERS = [
  { w: 11,  c: 'rgba(0,120,190,0.03)'  },
  { w: 5,   c: 'rgba(0,150,215,0.065)' },
  { w: 1.6, c: 'rgba(0,195,245,0.13)'  },
];

const TWIG_LAYERS = [
  { w: 5,   c: 'rgba(0,120,190,0.022)' },
  { w: 1.4, c: 'rgba(0,160,225,0.065)' },
];

/** Primary branch paths — organic side tunnels */
const BRANCHES = [
  // ── Entrance area
  'M90,310 C68,285 52,262 35,240',   'M90,310 C62,328 45,345 28,362',
  'M90,310 C58,306 35,302 14,296',
  // ── Entrance → Main corridor
  'M128,306 C118,278 108,252 96,232', 'M128,306 C115,330 105,352 92,370',
  'M178,296 C188,268 198,242 210,222','M178,296 C168,322 158,345 145,365',
  'M228,288 C238,262 248,238 260,220','M228,288 C218,314 208,336 195,355',
  // ── Main Junction
  'M290,280 C272,308 258,332 242,352','M290,280 C310,308 322,332 332,355',
  // ── Main → West
  'M325,260 C312,235 298,212 282,195','M325,260 C338,235 348,210 360,190',
  'M370,215 C355,192 340,170 325,152','M370,215 C385,192 398,168 412,148',
  'M412,175 C426,155 438,132 450,112','M412,175 C398,155 386,138 370,120',
  // ── Main → East
  'M355,290 C342,318 328,342 315,362','M355,290 C368,318 375,342 385,365',
  'M438,318 C450,345 460,368 472,390','M438,318 C425,345 418,370 408,395',
  'M520,342 C532,370 542,392 555,415','M520,342 C508,368 498,390 486,412',
  'M562,354 C572,378 582,400 595,420',
  // ── West Junction
  'M450,140 C468,118 480,96 492,75', 'M450,140 C432,118 420,98 408,78',
  // ── West → Zone A
  'M418,115 C405,94 390,74 375,58',  'M418,115 C432,94 445,72 458,55',
  'M382,88 C368,68 352,50 338,35',
  // ── Zone A
  'M350,65 C325,42 308,24 288,10',   'M350,65 C375,42 392,26 410,12',
  'M350,65 C335,48 318,34 300,20',
  // ── West → Zone B
  'M472,158 C485,138 498,118 512,98','M492,182 C508,162 522,140 535,122',
  // ── Zone B
  'M530,220 C558,198 578,175 598,155','M530,220 C555,242 572,260 590,278',
  'M530,220 C510,198 494,178 478,162',
  // ── East → Zone B
  'M582,315 C568,292 552,268 538,245','M568,288 C580,265 590,242 600,222',
  // ── East → Zone C
  'M638,338 C652,312 668,288 682,262','M638,338 C622,314 610,292 596,268',
  'M685,278 C698,255 712,235 728,215','M685,278 C672,255 660,238 648,218',
  // ── Zone C
  'M750,180 C778,162 800,142 822,125','M750,180 C775,200 795,218 815,238',
  'M750,180 C770,165 792,150 815,138',
  // ── East Junction
  'M600,360 C580,385 565,408 548,425','M600,360 C622,385 638,408 655,428',
  'M600,360 C614,380 630,400 645,418',
];

/** Secondary twigs — smaller extensions for density */
const TWIGS = [
  'M35,240 C22,222 12,205 2,190',     'M28,362 C15,378 5,392 -5,405',
  'M96,232 C85,215 72,200 58,188',    'M92,370 C78,385 65,396 50,405',
  'M210,222 C222,205 232,188 245,172','M145,365 C130,380 118,392 105,402',
  'M260,220 C272,202 284,185 298,170','M195,355 C182,370 168,382 152,392',
  'M242,352 C228,368 215,382 200,392','M332,355 C342,372 355,388 368,402',
  'M282,195 C268,178 252,162 238,148','M360,190 C372,172 385,155 398,140',
  'M325,152 C310,135 298,120 282,108','M450,112 C462,95 475,78 488,62',
  'M492,75 C505,58 518,42 532,28',    'M408,78 C395,62 382,48 368,35',
  'M288,10 C272,-2 258,-12 242,-20',  'M410,12 C425,0 440,-10 455,-18',
  'M472,390 C485,408 498,422 512,435','M408,395 C395,412 382,428 368,442',
  'M555,415 C568,432 580,445 595,455','M598,155 C612,138 628,122 642,108',
  'M590,278 C605,292 618,305 632,315','M822,125 C835,115 845,105 855,92',
  'M815,238 C828,252 838,262 848,272','M548,425 C532,440 518,452 502,462',
  'M655,428 C668,442 680,455 695,465',
];

/** Zone letter watermarks */
const ZONE_LETTERS = [
  { letter: 'A', x: 240, y: 90 },
  { letter: 'B', x: 510, y: 272 },
  { letter: 'C', x: 780, y: 230 },
];

/** Rescue-path layers (green) */
const RESCUE_LAYERS = [
  { w: 22, c: 'rgba(34,197,94,0.08)', ce: 'rgba(34,197,94,0.14)' },
  { w: 12, c: 'rgba(34,197,94,0.22)', ce: 'rgba(34,197,94,0.35)' },
  { w: 5,  c: 'rgba(34,197,94,0.55)', ce: 'rgba(34,197,94,0.75)' },
  { w: 2,  c: '#22c55e',              ce: '#4ade80'               },
];

/* ═══════════════════════════════════════════════════════ */

function getHazardLabel(reading) {
  if (!reading) return 'HAZARD ZONE';
  if (reading.gas_level >= THRESHOLDS.gas_level.warning) return 'GAS HAZARD';
  if (reading.temperature >= THRESHOLDS.temperature.warning) return 'HEAT HAZARD';
  if (reading.force >= THRESHOLDS.force.warning) return 'IMPACT ALERT';
  const hr = reading.heart_rate;
  if (hr > 0 && (hr <= THRESHOLDS.heart_rate.warningLow || hr >= THRESHOLDS.heart_rate.warningHigh))
    return 'VITAL ALERT';
  return 'HAZARD ZONE';
}

/* ═══════════════════════════════════════════════════════
   COMPONENT
   ═══════════════════════════════════════════════════════ */

export default function SurveillanceTunnelMap({ worker, reading, zone, status }) {
  const isDanger    = status === 'warning' || status === 'emergency';
  const isEmergency = status === 'emergency';
  const workerPos   = zone && NODES[zone] ? NODES[zone] : null;
  const rssi        = reading?.rssi ?? null;
  const workerLabel = worker?.name || worker?.worker_id || 'Worker';
  const statusLabel = isEmergency ? 'EMERGENCY' : isDanger ? 'WARNING' : 'ALL CLEAR';

  /** Rescue route via Dijkstra — only during danger */
  const rescueRoute = useMemo(() => {
    if (!isDanger || !zone || zone === 'Entrance') return [];
    return runDijkstra(TUNNEL_GRAPH, 'Entrance', zone);
  }, [isDanger, zone]);

  const rescueEdgeSet = useMemo(() => {
    const s = new Set();
    for (let i = 0; i < rescueRoute.length - 1; i++)
      s.add([rescueRoute[i], rescueRoute[i + 1]].sort().join('|'));
    return s;
  }, [rescueRoute]);

  const hazardLabel = isDanger ? getHazardLabel(reading) : '';
  const hzColor     = isEmergency ? '#ef4444' : '#f97316';

  return (
    <div className="surveillance-map-card">
      {/* ── Header ────────────────────────────────── */}
      <div className="surveillance-map-header">
        <div className="stm-header-left">
          <span className="surveillance-map-title">Tunnel Surveillance Map</span>
          <span className="surveillance-map-subtitle">Live position and rescue route guidance</span>
        </div>
        <span className={`stm-status-badge ${status || 'normal'}`}>
          <span className={`stm-status-dot ${status || 'normal'}`} />
          {statusLabel}
        </span>
      </div>

      {/* ── SVG Canvas ────────────────────────────── */}
      <div className="surveillance-map-canvas">
        {!workerPos && (
          <div className="stm-awaiting-overlay">
            <div className="stm-awaiting-icon">📡</div>
            <div className="stm-awaiting-text">Awaiting location data</div>
          </div>
        )}

        <svg viewBox={`0 0 ${VB_W} ${VB_H}`} preserveAspectRatio="xMidYMid meet">
          <defs>
            <pattern id="stm-grid" width="26" height="26" patternUnits="userSpaceOnUse">
              <path d="M 26 0 L 0 0 0 26" fill="none" stroke="rgba(0,130,210,0.035)" strokeWidth="0.4" />
            </pattern>
            <radialGradient id="stm-fog1" cx="28%" cy="48%" r="38%">
              <stop offset="0%" stopColor="rgba(0,70,150,0.055)" />
              <stop offset="100%" stopColor="rgba(0,0,0,0)" />
            </radialGradient>
            <radialGradient id="stm-fog2" cx="72%" cy="52%" r="32%">
              <stop offset="0%" stopColor="rgba(0,55,130,0.045)" />
              <stop offset="100%" stopColor="rgba(0,0,0,0)" />
            </radialGradient>
            <radialGradient id="stm-vig" cx="50%" cy="50%" r="56%">
              <stop offset="0%" stopColor="rgba(0,0,0,0)" />
              <stop offset="100%" stopColor="rgba(0,0,0,0.38)" />
            </radialGradient>
            <filter id="stm-wglow" x="-80%" y="-80%" width="260%" height="260%">
              <feGaussianBlur in="SourceGraphic" stdDeviation="5" result="b" />
              <feMerge><feMergeNode in="b" /><feMergeNode in="SourceGraphic" /></feMerge>
            </filter>
          </defs>

          {/* ── BG: dark fill + grid + fog + vignette ── */}
          <rect width={VB_W} height={VB_H} fill="#030712" />
          <rect width={VB_W} height={VB_H} fill="url(#stm-grid)" />
          <rect width={VB_W} height={VB_H} fill="url(#stm-fog1)" />
          <rect width={VB_W} height={VB_H} fill="url(#stm-fog2)" />
          <rect width={VB_W} height={VB_H} fill="url(#stm-vig)" />

          {/* ── Zone letter watermarks ──────────────── */}
          {ZONE_LETTERS.map((z) => (
            <text key={z.letter} x={z.x} y={z.y} fill="rgba(0,170,240,0.065)" fontSize={52}
              fontWeight="800" fontFamily="'Plus Jakarta Sans',sans-serif"
              textAnchor="middle" dominantBaseline="central"
              style={{ pointerEvents: 'none', userSelect: 'none' }}>
              {z.letter}
            </text>
          ))}

          {/* ── Secondary twigs (dimmest, bottom) ──── */}
          {TWIG_LAYERS.map((L, li) => (
            <g key={`tw-${li}`}>
              {TWIGS.map((d, i) => (
                <path key={`tw-${li}-${i}`} d={d} fill="none"
                  stroke={L.c} strokeWidth={L.w} strokeLinecap="round" />
              ))}
            </g>
          ))}

          {/* ── Primary branches ────────────────────── */}
          {BRANCH_LAYERS.map((L, li) => (
            <g key={`br-${li}`}>
              {BRANCHES.map((d, i) => (
                <path key={`br-${li}-${i}`} d={d} fill="none"
                  stroke={L.c} strokeWidth={L.w} strokeLinecap="round" />
              ))}
            </g>
          ))}

          {/* ── Main tunnel network (4 glow layers) ── */}
          {TUNNEL_LAYERS.map((L, li) => (
            <g key={`tl-${li}`}>
              {EDGES.map((e) => (
                <path key={`tl-${li}-${e.key}`} d={e.d} fill="none"
                  stroke={L.c} strokeWidth={L.w} strokeLinecap="round" />
              ))}
            </g>
          ))}

          {/* ── Rescue path (ONLY during danger) ───── */}
          {isDanger && rescueRoute.length > 1 && (
            <g className="stm-rescue-shimmer">
              {RESCUE_LAYERS.map((L, li) => (
                <g key={`rl-${li}`}>
                  {EDGES.filter((e) => rescueEdgeSet.has(e.key)).map((e) => (
                    <path key={`rl-${li}-${e.key}`} d={e.d} fill="none"
                      stroke={isEmergency ? L.ce : L.c} strokeWidth={L.w}
                      strokeLinecap="round" />
                  ))}
                </g>
              ))}
              {/* Animated dash overlay */}
              {EDGES.filter((e) => rescueEdgeSet.has(e.key)).map((e) => (
                <path key={`rd-${e.key}`} className="stm-rescue-dash-anim"
                  d={e.d} fill="none" stroke="rgba(255,255,255,0.22)"
                  strokeWidth={1.5} strokeLinecap="round" strokeDasharray="8 18" />
              ))}
            </g>
          )}

          {/* ── Hazard zone (ONLY during danger) ───── */}
          {isDanger && workerPos && (
            <g className={isEmergency ? 'stm-hazard-emergency' : 'stm-hazard-warning'}>
              <ellipse cx={workerPos.x} cy={workerPos.y}
                rx={isEmergency ? 75 : 60} ry={isEmergency ? 58 : 46}
                transform={`rotate(-15 ${workerPos.x} ${workerPos.y})`}
                fill={isEmergency ? 'rgba(239,68,68,0.055)' : 'rgba(249,115,22,0.035)'}
                stroke={isEmergency ? 'rgba(239,68,68,0.38)' : 'rgba(249,115,22,0.28)'}
                strokeWidth={1.5} strokeDasharray="9 5" />
              {/* Warning triangle */}
              <g transform={`translate(${workerPos.x},${workerPos.y - (isEmergency ? 78 : 64)})`}>
                <path d="M0,-10 L9,7 L-9,7 Z" fill="none" stroke={hzColor}
                  strokeWidth={1.4} strokeLinejoin="round" />
                <line x1={0} y1={-5} x2={0} y2={1.5} stroke={hzColor}
                  strokeWidth={1.6} strokeLinecap="round" />
                <circle cx={0} cy={4} r={1} fill={hzColor} />
              </g>
              <text x={workerPos.x} y={workerPos.y - (isEmergency ? 92 : 78)}
                textAnchor="middle" fill={hzColor} fontSize={8.5} fontWeight="700"
                fontFamily="'Plus Jakarta Sans',sans-serif" letterSpacing="0.1em">
                {hazardLabel}
              </text>
            </g>
          )}

          {/* ── Junction / zone nodes ───────────────── */}
          {Object.entries(NODES).map(([name, pos]) => {
            if (name === zone) return null; // worker marker handles active
            return (
              <g key={name}>
                <circle cx={pos.x} cy={pos.y} r={5.5}
                  fill="rgba(3,7,18,0.85)" stroke="rgba(0,190,240,0.28)" strokeWidth={1} />
                <circle cx={pos.x} cy={pos.y} r={2}
                  fill="rgba(0,210,255,0.38)" />
              </g>
            );
          })}

          {/* ── Entrance marker ─────────────────────── */}
          <g>
            <g transform={`translate(${NODES.Entrance.x - 34},${NODES.Entrance.y})`}>
              <rect x={-9} y={-4} width={18} height={13} rx={1}
                fill="none" stroke="rgba(0,200,245,0.35)" strokeWidth={1.1} />
              <path d="M-6,-4 L-6,-11 A6,8 0 0,1 6,-11 L6,-4"
                fill="none" stroke="rgba(0,200,245,0.35)" strokeWidth={1.1} />
            </g>
            <text x={NODES.Entrance.x - 34} y={NODES.Entrance.y + 24}
              textAnchor="middle" fill="rgba(0,200,245,0.45)" fontSize={7.5}
              fontWeight="700" fontFamily="'Plus Jakarta Sans',sans-serif"
              letterSpacing="0.1em">
              ENTRANCE
            </text>
          </g>

          {/* ── Worker marker ──────────────────────── */}
          {workerPos && (
            <g transform={`translate(${workerPos.x},${workerPos.y})`}>
              <g className="stm-worker-pulse-group" filter="url(#stm-wglow)">
                {/* Outer ring */}
                <circle r={24} fill="none" stroke="rgba(0,200,255,0.12)" strokeWidth={1} />
                {/* Middle ring */}
                <circle r={16} fill="rgba(0,200,255,0.04)"
                  stroke="rgba(0,212,255,0.25)" strokeWidth={1.5} />
                {/* Inner disc */}
                <circle r={10} fill="rgba(0,200,255,0.1)"
                  stroke="#00d4ff" strokeWidth={1.5} />
                {/* Person icon */}
                <circle cy={-5} r={2.8} fill="#00d4ff" />
                <rect x={-2.8} y={-1.5} width={5.6} height={5.5} rx={1.4} fill="#00d4ff" />
                <rect x={-2.5} y={4.5} width={2} height={4} rx={0.8} fill="#00d4ff" />
                <rect x={0.5} y={4.5} width={2} height={4} rx={0.8} fill="#00d4ff" />
              </g>
              {/* Name badge */}
              <rect x={-24} y={30} width={48} height={15} rx={5}
                fill="rgba(0,200,255,0.1)" stroke="rgba(0,200,255,0.18)" strokeWidth={0.6} />
              <text x={0} y={40.5} textAnchor="middle" fill="#00d4ff"
                fontSize={7.5} fontWeight="700"
                fontFamily="'JetBrains Mono','Fira Code',monospace">
                {workerLabel}
              </text>
            </g>
          )}

          {/* ── North indicator ─────────────────────── */}
          <g transform="translate(38,38)">
            <circle r={15} fill="none" stroke="rgba(0,180,240,0.18)" strokeWidth={0.7} />
            <path d="M0,-15 L-3.5,-7.5 L0,-10 L3.5,-7.5 Z" fill="rgba(0,200,245,0.4)" />
            <text y={2.5} textAnchor="middle" fill="rgba(0,200,245,0.45)"
              fontSize={9.5} fontWeight="700" fontFamily="'Plus Jakarta Sans',sans-serif">
              N
            </text>
          </g>

          {/* ── Scale bar ──────────────────────────── */}
          <g transform={`translate(32,${VB_H - 30})`}>
            <line x1={0} y1={0} x2={95} y2={0} stroke="rgba(140,160,190,0.25)" strokeWidth={0.7} />
            <line x1={0} y1={-3} x2={0} y2={3} stroke="rgba(140,160,190,0.25)" strokeWidth={0.7} />
            <line x1={47} y1={-2} x2={47} y2={2} stroke="rgba(140,160,190,0.25)" strokeWidth={0.7} />
            <line x1={95} y1={-3} x2={95} y2={3} stroke="rgba(140,160,190,0.25)" strokeWidth={0.7} />
            {['0', '75', '150m'].map((t, i) => (
              <text key={t} x={i * 47.5} y={13} textAnchor="middle"
                fill="rgba(140,160,190,0.3)" fontSize={6.5}
                fontFamily="'JetBrains Mono',monospace">
                {t}
              </text>
            ))}
          </g>
        </svg>
      </div>

      {/* ── Footer ────────────────────────────────── */}
      <div className="surveillance-map-footer">
        <div className="surveillance-map-legend">
          <span className="stm-legend-chip"><span className="stm-legend-swatch tunnel" />Tunnel Network</span>
          <span className="stm-legend-chip"><span className="stm-legend-swatch worker" />Worker Position</span>
          <span className="stm-legend-chip"><span className="stm-legend-swatch rescue" />Rescue Path</span>
          <span className="stm-legend-chip"><span className="stm-legend-swatch hazard" />Hazard Zone</span>
        </div>
        <div className="surveillance-map-summary">
          <div className="stm-summary-item">
            <span className="stm-summary-label">Zone</span>
            <span className="stm-summary-value zone">{zone || '—'}</span>
          </div>
          <div className="stm-summary-item">
            <span className="stm-summary-label">RSSI</span>
            <span className="stm-summary-value rssi">{rssi != null ? `${rssi} dBm` : '—'}</span>
          </div>
          <span className="stm-summary-note">Estimated by signal strength</span>
        </div>
      </div>
    </div>
  );
}
